u+2}{2k}z^2- rac{ho^4z^4}{4k},\  rac{n+1}{4k^2}z^4 igr]$이므로 $ rac{n+1}{2k}\cdot rac1{128}\le rac1{100}$이면 $|\mathrm{Mag}^{\mathrm J}_k\mathrm{Am}_ho-e^{-z^2/2}|\le k^{-1} igl[ rac{
u+2}2z^2+ rac{n+1}{4k}z^4+ rac{ho^4z^4}4 igr]e^{-0.49z^2}$이다. 위상 $\mathrm{Ph}^{\mathrm J}_ho(z)=\mathrm{Ph}_k(z)-ho z/\sqrt k-(k-1) igl(ho z/\sqrt k-\arctan(ho z/\sqrt k) igr)$는 $z\ge0$에서 $\sqrt k\,\mathrm{Ph}^{\mathrm J}_ho\le rac{2-ho^3}3z^3-ho z+k^{-1} igl[ rac{(
